import SwiftUIimport FirebaseAuthimport FirebaseFirestore // Required to talk to the databasestruct SignupView: View {    @Environment(\.dismiss) var dismiss    @State private var name = "" // Added Name field    @State private var email = ""    @State private var password = ""    @State private var confirmPassword = ""    @State private var errorMessage = ""    @State private var successMessage = ""    @State private var agreedToTerms = false    @State private var isLoading = false            var body: some View {        ZStack {            Color.orange.ignoresSafeArea()                        VStack(spacing: 20) {                Image("GrubULogo")                    .resizable()                    .scaledToFit()                                Text("Create Account")                    .font(.system(size: 40, weight: .bold))                    .foregroundColor(.white)                    .padding(.bottom, 30)                Text("Create your account to get started.")                    .font(.system(size: 16, weight: .semibold))                    .foregroundColor(.white)                                // New Name Input                TextField("Full Name", text: $name)                    .textFieldStyle(.roundedBorder)                    .padding(.horizontal, 30)                                TextField("University Email (.edu)", text: $email)                    .textFieldStyle(.roundedBorder)                    .autocapitalization(.none)                    .keyboardType(.emailAddress)                    .padding(.horizontal, 30)                                SecureField("Password", text: $password)                    .textFieldStyle(.roundedBorder)                    .padding(.horizontal, 30)                                SecureField("Confirm Password", text: $confirmPassword)                    .textFieldStyle(.roundedBorder)                    .padding(.horizontal, 30)                                /*if !errorMessage.isEmpty {                    Text(errorMessage)                        .foregroundColor(.white)                        .font(.subheadline)                        .bold()                }*/                                HStack(alignment: .top, spacing: 10){                    Button{ agreedToTerms.toggle()} label: {                        ZStack{                            RoundedRectangle(cornerRadius: 4)                                .stroke(Color.white, lineWidth: 2)                                .frame(width: 24, height: 24)                                                        if agreedToTerms {                                Image(systemName: "checkmark")                                    .foregroundColor(.white)                                    .font(.system(size: 14, weight: .bold))                            }                        }                    }                    Text("I agree to the Terms of Service and Privacy Policy.")                        .font(.system(size: 14, weight: .semibold))                        .foregroundColor(.white)                        .multilineTextAlignment(.leading)                                        Spacer()                }                .padding(.horizontal, 30)                                if !errorMessage.isEmpty {                    Text(errorMessage)                        .foregroundColor(.white)                        .font(.subheadline)                        .bold()                        .multilineTextAlignment(.center)                        .padding(.horizontal)                }                                if !successMessage.isEmpty {                    Text(successMessage)                        .foregroundColor(.green)                        .font(.subheadline)                        .bold()                        .multilineTextAlignment(.center)                        .padding(.horizontal)                }                                Button(action: registerUser) {                    Text(isLoading ? "Signing Up..." : "Sign Up")                        .font(.headline)                        .foregroundColor(.orange)                        .frame(maxWidth: .infinity)                        .padding()                        .background(Color.white)                        .cornerRadius(12)                        .shadow(color: .black.opacity(0.5), radius: 6, x: 0, y: 4)                }                .padding(.horizontal, 30)                .padding(.top, 10)                .disabled(isLoading)                                Button{                    dismiss()                } label: {                    Text("Already have an account? Login")                        .foregroundColor(.white)                        .underline()                }                .padding(.top, 10)            }            .padding(.vertical)        }        .tint(.white)    }        func registerUser() {        errorMessage = ""        successMessage = ""                guard !name.trimmingCharacters(in: .whitespaces).isEmpty else {            errorMessage = "Please enter your full name."            return        }                guard email.lowercased().hasSuffix(".edu") else {            errorMessage = "Please use a valid .edu email address."            return        }                guard password.count >= 6 else {            errorMessage = "Password must be at least 6 characters."            return        }                guard password == confirmPassword else {            errorMessage = "Passwords do not match."            return        }                guard agreedToTerms else {            errorMessage = "You must agree to the Terms of Service and Privacy Policy."            return        }                isLoading = true                        Auth.auth().createUser(withEmail: email, password: password) { result, error in            if let error = error {                isLoading = false                errorMessage = error.localizedDescription                return            }                        guard let user = result?.user else {                isLoading = false                errorMessage = "Could not create account."                return }            let changeRequest = user.createProfileChangeRequest()            changeRequest.displayName = name            changeRequest.commitChanges{ _ in                                                user.sendEmailVerification { error in                    if let error = error {                        isLoading = false                        errorMessage = "Failed to send verification email: \(error.localizedDescription)"                        return                    }                                        // 1. Create the database reference                    let db = Firestore.firestore()                                        // 2. Build the cleanly formatted Swift Struct                    let newUser = User(                        uid: user.uid,                        email: email,                        displayName: name,                        university: "Washington University in St. Louis",                        usdBalance: 0.0,                        isBankLinked: false,                        rating: 5.0,                        completedOrders: 0                    )                                        // 3. Save the struct using 'setData(from:)'                    do {                        try db.collection("users").document(user.uid).setData(from: newUser)                        successMessage = "Success! A verification link has been sent to \(email). Please click it to activate your account."                        try? Auth.auth().signOut()                    } catch {                        errorMessage = "Account created, but database failed: \(error.localizedDescription)"                    }                    isLoading = false                }            }        }    }}        #Preview {        SignupView()    }